<div id="readout" style="margin-top:4px;padding:6px 7px;background:#f2f6f9;border:1px solid #d6e0e8;border-radius:4px;font-family:ui-monospace,Consolas,monospace;font-size:11px;line-height:1.5;white-space:pre"></div>
<div style="display:flex;gap:4px;margin-top:4px">
  <button id="btnPrev">&#9664; Prev</button>
  <button id="btnNext">Next step &#9654;</button>
</div>
<div id="narr" style="font-size:11px;line-height:1.4;color:#333;min-height:44px"></div>
<div style="font-size:10px;color:#666;line-height:1.4">Drag to orbit: the curve is a true helix — its shadow on the <i>xy</i>-plane is the upper unit semicircle.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ────────────────────────────────────────────────────────
   box wireframe      → LineSegments, 12 edges, x[-1,1] y[0,1] z[0,PI]  black
   helix C            → TubeGeometry(Curve r(t)=(cos t,sin t,t)) r=0.03  #29ABE2
   traced part 0..t   → TubeGeometry(sub-curve) r=0.034                  #0B6FA4
   arrowhead @ t=2    → ConeGeometry(0.075,0.2) tangent-aligned          #29ABE2
   start dot (1,0,0)  → SphereGeometry(0.065)                            #29ABE2
   end dot (-1,0,PI)  → SphereGeometry(0.065)                            #29ABE2
   leader arrow       → Line + ConeGeometry(0.035,0.11)                  black
   x=0 tick           → Line (short)                                     black
   sample point       → SphereGeometry(0.075)                            #F5821F
   ds sub-arc [t,t+.15]→ TubeGeometry r=0.055                            #F5821F
   integrand stem     → CylinderGeometry(0.02,0.02,1) scaled in Y        #2CA02C
   all text           → addLabel (HTML)
   world = (math y, math z, math x)  so math z is screen-up
