// @FIGURE_CODE_BEGIN
/* ── Element spec ────────────────────────────────────────────────────────
   box wireframe      → LineSegments, 12 edges, x[-1,1] y[0,1] z[0,PI]  black
   helix C            → TubeGeometry(Curve r(t)=(cos t,sin t,t)) r=0.03  #29ABE2
   traced part 0..t   → TubeGeometry(sub-curve) r=0.034                  #0B6FA4
   arrowhead @ t=2    → ConeGeometry(0.075,0.2) tangent-aligned          #29ABE2
   start dot (1,0,0)  → SphereGeometry(0.065)                            #29ABE2
   end dot (-1,0,PI)  → SphereGeometry(0.065)                            #29ABE2
   leader arrow       → Line + ConeGeometry(0.035,0.11)                  black
   x=0 tick           → Line (short)                                     black
   sample point       → SphereGeometry(0.075)                            #F5821F
   ds sub-arc [t,t+.15]→ TubeGeometry r=0.055                            #F5821F
   integrand stem     → CylinderGeometry(0.02,0.02,1) scaled in Y        #2CA02C
   all text           → addLabel (HTML)
   world = (math y, math z, math x)  so math z is screen-up
   ──────────────────────────────────────────────────────────────────── */

const PI = Math.PI;
const BLUE = 0x29ABE2, DEEP = 0x0B6FA4, ORANGE = 0xF5821F, GREEN = 0x2CA02C;
const M = (x, y, z) => new THREE.Vector3(y, z, x);   // math -> world

/* ── box wireframe ─────────────────────────────────────────────────────── */
const boxPts = [];
for (const y of [0, 1]) for (const z of [0, PI]) boxPts.push(M(-1, y, z), M(1, y, z));
for (const x of [-1, 1]) for (const z of [0, PI]) boxPts.push(M(x, 0, z), M(x, 1, z));
for (const x of [-1, 1]) for (const y of [0, 1]) boxPts.push(M(x, y, 0), M(x, y, PI));
const boxLines = new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(boxPts),
  new THREE.LineBasicMaterial({ color: 0x000000 })
);
scene.add(boxLines);
registerInteractive(boxLines, {
  title: 'Bounding box',
  tooltip: 'Coordinate box  x∈[−1,1], y∈[0,1], z∈[0,π]',
  body: 'The box is the bounding box of the helix: x = cos t ∈ [−1,1], y = sin t ∈ [0,1] (upper semicircle only), z = t ∈ [0,π].'
});

// tick mark at x = 0 on the front bottom edge
scene.add(new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints([M(0.0, 1, 0.06), M(0.0, 1, -0.06)]),
  new THREE.LineBasicMaterial({ color: 0x000000 })
));

/* ── helix curve ───────────────────────────────────────────────────────── */
class Helix extends THREE.Curve {
  constructor(a, b) { super(); this.a = a; this.b = b; }
  getPoint(u, target = new THREE.Vector3()) {
    const t = this.a + (this.b - this.a) * u;
    return target.set(Math.sin(t), t, Math.cos(t));   // (y, z, x)
  }
}
const helixMesh = new THREE.Mesh(
  new THREE.TubeGeometry(new Helix(0, PI), 220, 0.03, 14, false),
  new THREE.MeshBasicMaterial({ color: BLUE })
);
scene.add(helixMesh);
registerInteractive(helixMesh, {
  title: 'The curve C',
  tooltip: 'Helix r(t) = (cos t, sin t, t)',
  body: 'C is the helix r(t) = ⟨cos t, sin t, t⟩ for 0 ≤ t ≤ π. Since |r′(t)| = √(sin²t + cos²t + 1) = √2, the arc-length element is ds = √2 dt and the total length is √2·π ≈ 4.44.'
});

const traceMesh = new THREE.Mesh(
  new THREE.TubeGeometry(new Helix(0, 0.05), 6, 0.034, 12, false),
  new THREE.MeshBasicMaterial({ color: DEEP })
);
traceMesh.visible = false;
scene.add(traceMesh);

/* ── arrowhead at t = 2 ────────────────────────────────────────────────── */
const tA = 2.0;
const arrow = new THREE.Mesh(
  new THREE.ConeGeometry(0.075, 0.21, 16),
  new THREE.MeshBasicMaterial({ color: BLUE })
);
arrow.position.set(Math.sin(tA), tA, Math.cos(tA));
arrow.quaternion.setFromUnitVectors(
  new THREE.Vector3(0, 1, 0),
  new THREE.Vector3(Math.cos(tA), 1, -Math.sin(tA)).normalize()
);
scene.add(arrow);

/* ── endpoint dots ─────────────────────────────────────────────────────── */
const dotGeo = new THREE.SphereGeometry(0.065, 20, 14);
const dotMat = new THREE.MeshBasicMaterial({ color: BLUE });
const startDot = new THREE.Mesh(dotGeo, dotMat); startDot.position.copy(M(1, 0, 0));
const endDot = new THREE.Mesh(dotGeo, dotMat); endDot.position.copy(M(-1, 0, PI));
scene.add(startDot, endDot);
registerInteractive(startDot, { title: 'Initial point (1, 0, 0)', tooltip: 't = 0', body: 'At t = 0: r(0) = (cos 0, sin 0, 0) = (1, 0, 0). This is the lower corner of the box where C begins.' });
registerInteractive(endDot, { title: 'Terminal point (−1, 0, π)', tooltip: 't = π', body: 'At t = π: r(π) = (cos π, sin π, π) = (−1, 0, π). Half a turn around the z-axis, risen to height π.' });

/* ── leader arrow to the start point ───────────────────────────────────── */
const leadFrom = new THREE.Vector3(0, -0.30, 1.42);
const leadTo = new THREE.Vector3(0, -0.09, 1.12);
scene.add(new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([leadFrom, leadTo]),
  new THREE.LineBasicMaterial({ color: 0x000000 })
));
const leadHead = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.11, 12), new THREE.MeshBasicMaterial({ color: 0x000000 }));
leadHead.position.copy(leadTo);
leadHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), leadTo.clone().sub(leadFrom).normalize());
scene.add(leadHead);

/* ── moving sample point, ds segment, integrand stem ───────────────────── */
const sample = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 14), new THREE.MeshBasicMaterial({ color: ORANGE }));
sample.position.copy(M(1, 0, 0));
scene.add(sample);

const dsMesh = new THREE.Mesh(
  new THREE.TubeGeometry(new Helix(0, 0.15), 10, 0.055, 12, false),
  new THREE.MeshBasicMaterial({ color: ORANGE })
);
dsMesh.visible = false;
scene.add(dsMesh);

const stemGeo = new THREE.CylinderGeometry(0.02, 0.02, 1, 10);
stemGeo.translate(0, 0.5, 0);
const stem = new THREE.Mesh(stemGeo, new THREE.MeshBasicMaterial({ color: GREEN }));
stem.visible = false;
scene.add(stem);
const stemCap = new THREE.Mesh(new THREE.SphereGeometry(0.05, 14, 10), new THREE.MeshBasicMaterial({ color: GREEN }));
stemCap.visible = false;
scene.add(stemCap);

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  target: [0, PI / 2, 0],
  heightFraction: 0.65
});
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = (s) => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">${s}</span>`;
const NUM = '17px';

addLabel('(&minus;1, 0, ' + SER('&pi;') + ')', M(-1, 0, PI), { fontSize: NUM, offset: [-62, -14] });
addLabel('(1, 0, 0)', new THREE.Vector3(0, -0.40, 1.52), { fontSize: NUM, offset: [-4, 12] });

addLabel('0', M(-1, 0, PI), { fontSize: NUM, offset: [30, -20] });          // y tick 0
addLabel(SER('y'), M(-1, 0.5, PI), { fontSize: '20px', offset: [46, -38] });  // y axis
addLabel('1', M(-1, 1, PI), { fontSize: NUM, offset: [18, -26] });           // y tick 1

addLabel(SER('z'), M(1, 0, PI / 2), { fontSize: '20px', offset: [-36, 0] });   // z axis
addLabel('0', M(1, 0, 0), { fontSize: NUM, offset: [-28, 2] });              // z tick 0
addLabel(SER('&pi;'), M(1, 0, PI), { fontSize: NUM, offset: [-28, 0] });      // z tick pi

addLabel(SER('x'), M(0, 1, 0), { fontSize: '20px', offset: [8, 46] });        // x axis
addLabel('0', M(0, 1, 0), { fontSize: NUM, offset: [-2, 22] });              // x tick 0
addLabel('1', M(1, 1, 0), { fontSize: NUM, offset: [2, 28] });               // x tick 1
addLabel('&minus;1', M(-1, 1, 0), { fontSize: NUM, offset: [26, 14] });      // x tick -1

addLabel(SER('C'), new THREE.Vector3(Math.sin(1.15) + 0.05, 1.15, Math.cos(1.15)), { fontSize: '18px', color: '#1580b5', offset: [26, 10] });

const dsLabel = addLabel('', new THREE.Vector3(), { fontSize: '13px', color: '#c25c00', bold: true, offset: [26, -12] });
const fLabel = addLabel('', new THREE.Vector3(), { fontSize: '13px', color: '#1a7a1a', bold: true, offset: [30, -10] });

/* ── state + update ────────────────────────────────────────────────────── */
const state = { t: 0, mode: 'curve' };
const slider = document.getElementById('tSlider');
const tVal = document.getElementById('tVal');
const readout = document.getElementById('readout');
const narr = document.getElementById('narr');
const btns = { curve: document.getElementById('mCurve'), ds: document.getElementById('mDs'), f: document.getElementById('mF') };

const fVal = (t) => Math.cos(t) * Math.sin(t) + t * t * t;
const F_MAX = PI * PI * PI;

function update() {
  const t = state.t;
  const x = Math.cos(t), y = Math.sin(t), z = t;
  const wp = new THREE.Vector3(y, z, x);
  sample.position.copy(wp);

  // traced portion
  if (t > 0.04) {
    traceMesh.visible = true;
    const g = traceMesh.geometry;
    traceMesh.geometry = new THREE.TubeGeometry(new Helix(0, t), Math.max(8, Math.round(60 * t / PI) + 8), 0.034, 12, false);
    g.dispose();
  } else {
    traceMesh.visible = false;
  }

  // ds sub-arc
  const a = Math.min(t, PI - 0.15), b = a + 0.15;
  if (state.mode === 'ds') {
    const g2 = dsMesh.geometry;
    dsMesh.geometry = new THREE.TubeGeometry(new Helix(a, b), 10, 0.055, 12, false);
    g2.dispose();
    dsMesh.visible = true;
    const mid = new THREE.Vector3(Math.sin((a + b) / 2), (a + b) / 2, Math.cos((a + b) / 2));
    dsLabel.pos.copy(mid);
    dsLabel.div.innerHTML = 'ds = &radic;2 &Delta;t &asymp; ' + (Math.SQRT2 * 0.15).toFixed(3);
  } else {
    dsMesh.visible = false;
    dsLabel.div.innerHTML = '';
  }

  // integrand stem
  const f = fVal(t);
  const h = Math.max(0, Math.min(1.5, 1.5 * f / F_MAX));
  if (state.mode === 'f' && h > 0.004) {
    stem.visible = true; stemCap.visible = true;
    stem.position.copy(wp); stem.scale.set(1, h, 1);
    stemCap.position.set(wp.x, wp.y + h, wp.z);
    fLabel.pos.set(wp.x, wp.y + h, wp.z);
    fLabel.div.innerHTML = 'f = ' + f.toFixed(2);
  } else {
    stem.visible = false; stemCap.visible = false;
    fLabel.div.innerHTML = '';
  }

  const acc = Math.SQRT2 * (Math.sin(t) * Math.sin(t) / 2 + Math.pow(t, 4) / 4);
  tVal.textContent = t.toFixed(2);
  slider.value = t;
  readout.textContent =
    't = ' + t.toFixed(3) + '\n' +
    '(x, y, z) = (' + x.toFixed(2) + ', ' + y.toFixed(2) + ', ' + z.toFixed(2) + ')\n' +
    'f = xy + z\u00b3 = ' + f.toFixed(3) + '\n' +
    '|r\u2032(t)| = \u221a2  \u2192  ds = \u221a2 dt\n' +
    '\u222b\u2080\u1d57 f ds = ' + acc.toFixed(3) + '\n' +
    'total = \u221a2\u00b7\u03c0\u2074/4 = ' + (Math.SQRT2 * Math.pow(PI, 4) / 4).toFixed(3);
}

function setMode(m) {
  state.mode = m;
  for (const k in btns) btns[k].classList.toggle('active', k === m);
  update();
}
btns.curve.onclick = () => setMode('curve');
btns.ds.onclick = () => setMode('ds');
btns.f.onclick = () => setMode('f');

slider.addEventListener('input', () => { anim = null; state.t = parseFloat(slider.value); update(); });

/* ── tweening / animation ──────────────────────────────────────────────── */
let anim = null;
const ease = (p) => p * p * (3 - 2 * p);
function tweenTo(target, dur) {
  anim = { from: state.t, to: target, start: performance.now(), dur: dur, linear: false };
}
document.getElementById('btnTrace').addEventListener('click', () => {
  state.t = 0; update();
  anim = { from: 0, to: PI, start: performance.now(), dur: 6000, linear: true };
});

(function loop() {
  requestAnimationFrame(loop);
  if (anim) {
    const p = Math.min(1, (performance.now() - anim.start) / anim.dur);
    const e = anim.linear ? p : ease(p);
    state.t = anim.from + (anim.to - anim.from) * e;
    update();
    if (p >= 1) anim = null;
  }
})();

/* ── demo steps ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Start of the path', text: 'At t = 0 the point sits at (1, 0, 0) on the bottom of the box, the labeled starting point of C.', t: 0, mode: 'curve' },
  { title: 'A quarter turn up', text: 'At t = \u03c0/2 the point is at (0, 1, \u03c0/2): the helix has swung a quarter turn in y while rising halfway up the box.', t: 1.5708, mode: 'ds' },
  { title: 'Weighting by the integrand', text: 'Each arc piece ds = \u221a2 dt is multiplied by f = xy + z\u00b3 = cos t sin t + t\u00b3; watch the weight grow rapidly as z climbs.', t: 2.4, mode: 'f' },
  { title: 'End of the path', text: 'At t = \u03c0 the point reaches (\u22121, 0, \u03c0) at the top back corner, completing the half-turn helix.', t: 3.14159, mode: 'f' }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setMode(s.mode);
  tweenTo(s.t, 900);
  narr.innerHTML = '<b>' + (stepIdx + 1) + '. ' + s.title + '</b><br>' + s.text;
}
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);

narr.innerHTML = '<b>Explore</b><br>Drag the t slider, switch the display mode, or step through the demo.';
setMode('curve');
update();
// @FIGURE_CODE_END

