   display map  W(x,y,z) = ( K.y*(y-0.5), K.z*(z-PI/2), K.x*x )
        three-Y = math z (screen up), three-X = math y, three-Z = math x
        K = {1, 2, 2/PI} reproduces the source's cubic-looking box;
        K = {1, 1, 1}    is the true metric shape.
   ──────────────────────────────────────────────────────────────────── */

const PI = Math.PI;
const BLUE = 0x29ABE2, DEEP = 0x0B6FA4, ORANGE = 0xF5821F, GREEN = 0x2CA02C;

const K_FIG = { x: 1, y: 2, z: 2 / PI };
const K_TRUE = { x: 1, y: 1, z: 1 };
const K = { x: K_FIG.x, y: K_FIG.y, z: K_FIG.z };

function W(x, y, z) {
  return new THREE.Vector3(K.y * (y - 0.5), K.z * (z - PI / 2), K.x * x);
}
function tangentAt(t) {
  return new THREE.Vector3(K.y * Math.cos(t), K.z, -K.x * Math.sin(t)).normalize();
}
const UPV = new THREE.Vector3(0, 1, 0);

/* ── box wireframe ─────────────────────────────────────────────────────── */
const boxBlack = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x000000 }));
const boxGrey = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0xc8c8c8 }));
const tickLine = new THREE.LineSegments(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x000000 }));
scene.add(boxBlack, boxGrey, tickLine);

const CORNERS = [];
for (const cx of [-1, 1]) for (const cy of [0, 1]) for (const cz of [0, PI]) CORNERS.push([cx, cy, cz]);
const isFar = (p) => p[0] === -1 && p[1] === 0 && p[2] === 0;   // hidden back-bottom corner

function buildBox() {
  const blk = [], gry = [];
  for (let i = 0; i < 8; i++) for (let j = i + 1; j < 8; j++) {
    const a = CORNERS[i], b = CORNERS[j];
    let diff = 0;
    for (let k = 0; k < 3; k++) if (a[k] !== b[k]) diff++;
    if (diff !== 1) continue;
    const arr = (isFar(a) || isFar(b)) ? gry : blk;
    arr.push(W(a[0], a[1], a[2]), W(b[0], b[1], b[2]));
  }
  boxBlack.geometry.dispose();
  boxBlack.geometry = new THREE.BufferGeometry().setFromPoints(blk);
  boxGrey.geometry.dispose();
  boxGrey.geometry = new THREE.BufferGeometry().setFromPoints(gry);
  tickLine.geometry.dispose();
  tickLine.geometry = new THREE.BufferGeometry().setFromPoints([W(0, 0.92, 0), W(0, 1.10, 0)]);
}

registerInteractive(boxBlack, {
  title: 'Bounding box',
  tooltip: 'Coordinate box  x∈[−1,1], y∈[0,1], z∈[0,π]',
  body: 'The box frames the helix: x = cos t ∈ [−1,1], y = sin t ∈ [0,1] (only the upper semicircle is traced), z = t ∈ [0,π]. The textbook draws it as a cube, so the y-direction is stretched on the page; the "True scale" button removes that stretch.'
});

/* ── helix curve ───────────────────────────────────────────────────────── */
class Helix extends THREE.Curve {
  constructor(a, b) { super(); this.a = a; this.b = b; }
  getPoint(u, target = new THREE.Vector3()) {
    const t = this.a + (this.b - this.a) * u;
    return target.copy(W(Math.cos(t), Math.sin(t), t));
  }
}
const helixMesh = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ color: BLUE }));
scene.add(helixMesh);
registerInteractive(helixMesh, {
  title: 'The curve C',
  tooltip: 'Helix r(t) = (cos t, sin t, t)',
  body: 'C is the helix r(t) = ⟨cos t, sin t, t⟩ for 0 ≤ t ≤ π. Since |r′(t)| = √(sin²t + cos²t + 1) = √2, the arc-length element is ds = √2 dt and the total length is √2·π ≈ 4.44.'
});

const traceMesh = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ color: DEEP }));
traceMesh.visible = false;
scene.add(traceMesh);

/* ── arrowhead, dots, leader ───────────────────────────────────────────── */
const T_ARROW = 2.0;
const arrow = new THREE.Mesh(new THREE.ConeGeometry(0.105, 0.30, 18),
  new THREE.MeshBasicMaterial({ color: BLUE }));
scene.add(arrow);

const dotGeo = new THREE.SphereGeometry(0.07, 20, 14);
const dotMat = new THREE.MeshBasicMaterial({ color: BLUE });
const startDot = new THREE.Mesh(dotGeo, dotMat);
const endDot = new THREE.Mesh(dotGeo, dotMat);
scene.add(startDot, endDot);
registerInteractive(startDot, { title: 'Initial point (1, 0, 0)', tooltip: 't = 0', body: 'At t = 0: r(0) = (cos 0, sin 0, 0) = (1, 0, 0). This is the lower-left corner of the box where C begins.' });
registerInteractive(endDot, { title: 'Terminal point (−1, 0, π)', tooltip: 't = π', body: 'At t = π: r(π) = (cos π, sin π, π) = (−1, 0, π). Half a turn around the z-axis, risen to height π.' });

const leadLine = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x000000 }));
const leadHead = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.11, 12),
  new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(leadLine, leadHead);

/* ── moving sample point, ds segment, integrand stem ───────────────────── */
const sample = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 14),
  new THREE.MeshBasicMaterial({ color: ORANGE }));
sample.visible = false;
scene.add(sample);

const dsMesh = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ color: ORANGE }));
dsMesh.visible = false;
scene.add(dsMesh);

const stemGeo = new THREE.CylinderGeometry(0.02, 0.02, 1, 10);
stemGeo.translate(0, 0.5, 0);
const stem = new THREE.Mesh(stemGeo, new THREE.MeshBasicMaterial({ color: GREEN }));
stem.visible = false;
scene.add(stem);
const stemCap = new THREE.Mesh(new THREE.SphereGeometry(0.05, 14, 10),
  new THREE.MeshBasicMaterial({ color: GREEN }));
stemCap.visible = false;
scene.add(stemCap);

/* ── labels (math coords, re-projected whenever the scale changes) ─────── */
const LBL = [];
function L(html, m, opts) {
  const e = addLabel(html, W(m[0], m[1], m[2]), opts);
  LBL.push({ e, m });
  return e;
}
function refreshLabels() {
  for (const { e, m } of LBL) e.pos.copy(W(m[0], m[1], m[2]));
}

/* ── rebuild everything that depends on the display scale ──────────────── */
let ready = false;
function rebuild() {
  buildBox();

  helixMesh.geometry.dispose();
  helixMesh.geometry = new THREE.TubeGeometry(new Helix(0, PI), 200, 0.035, 14, false);

  arrow.position.copy(W(Math.cos(T_ARROW), Math.sin(T_ARROW), T_ARROW));
  arrow.quaternion.setFromUnitVectors(UPV, tangentAt(T_ARROW));

  startDot.position.copy(W(1, 0, 0));
  endDot.position.copy(W(-1, 0, PI));

  const p0 = W(1.62, 0, -0.42), p1 = W(1.16, 0, -0.12);
  leadLine.geometry.dispose();
  leadLine.geometry = new THREE.BufferGeometry().setFromPoints([p0, p1]);
  leadHead.position.copy(p1);
  leadHead.quaternion.setFromUnitVectors(UPV, p1.clone().sub(p0).normalize());

  refreshLabels();
  if (ready) update();
}
rebuild();

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  target: [0, 0, 0],
  heightFraction: 0.62
});
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = (s) => `<span style="font-family:Georgia,'Times New Roman',serif;font-style:italic">${s}</span>`;
const NUM = '17px';
const AX = '20px';

L('(&minus;1, 0, ' + SER('&pi;') + ')', [-1, 0, PI], { fontSize: NUM, offset: [-64, -12] });
L('0', [-1, 0, PI], { fontSize: NUM, offset: [26, -20] });            // y tick 0
L(SER('y'), [-1, 0.5, PI], { fontSize: AX, offset: [34, -34] });      // y axis letter
L('1', [-1, 1, PI], { fontSize: NUM, offset: [26, -12] });            // y tick 1

L(SER('z'), [1, 0, PI / 2], { fontSize: AX, offset: [-32, 0] });      // z axis letter
L('0', [1, 0, 0], { fontSize: NUM, offset: [-26, -2] });              // z tick 0
L(SER('&pi;'), [1, 0, PI], { fontSize: NUM, offset: [-26, 0] });      // z tick pi

L('1', [1, 1, 0], { fontSize: NUM, offset: [-4, 26] });               // x tick 1
L('0', [0, 1, 0], { fontSize: NUM, offset: [2, 26] });                // x tick 0
L(SER('x'), [0, 1, 0], { fontSize: AX, offset: [2, 50] });            // x axis letter
L('&minus;1', [-1, 1, 0], { fontSize: NUM, offset: [22, -8] });       // x tick -1

L('(1, 0, 0)', [1.72, 0, -0.52], { fontSize: NUM, offset: [-6, 12] });

const dsLabel = addLabel('', new THREE.Vector3(), { fontSize: '13px', color: '#c25c00', bold: true, offset: [30, -12] });
const fLabel = addLabel('', new THREE.Vector3(), { fontSize: '13px', color: '#1a7a1a', bold: true, offset: [32, -10] });
refreshLabels();

/* ── state + update ────────────────────────────────────────────────────── */
const state = { t: 0, mode: 'curve' };
const slider = document.getElementById('tSlider');
const tVal = document.getElementById('tVal');
const readout = document.getElementById('readout');
const narr = document.getElementById('narr');
const btns = {
  curve: document.getElementById('mCurve'),
  ds: document.getElementById('mDs'),
  f: document.getElementById('mF')
};

const fVal = (t) => Math.cos(t) * Math.sin(t) + t * t * t;
const F_MAX = PI * PI * PI;

function update() {
  const t = state.t;
  const x = Math.cos(t), y = Math.sin(t), z = t;
  const p = W(x, y, z);
  sample.position.copy(p);
  sample.visible = t > 0.03;                 // keep the blue start dot clean at t = 0

  // traced portion
  if (t > 0.04) {
    traceMesh.visible = true;
    const g = traceMesh.geometry;
    traceMesh.geometry = new THREE.TubeGeometry(
      new Helix(0, t), Math.max(8, Math.round(120 * t / PI) + 8), 0.040, 12, false);
    g.dispose();
  } else {
    traceMesh.visible = false;
  }

  // ds sub-arc
  const a = Math.min(t, PI - 0.15), b = a + 0.15;
  if (state.mode === 'ds') {
    const g2 = dsMesh.geometry;
    dsMesh.geometry = new THREE.TubeGeometry(new Helix(a, b), 10, 0.06, 12, false);
    g2.dispose();
    dsMesh.visible = true;
    const mt = (a + b) / 2;
    dsLabel.pos.copy(W(Math.cos(mt), Math.sin(mt), mt));
    dsLabel.div.innerHTML = 'ds = &radic;2 &Delta;t &asymp; ' + (Math.SQRT2 * 0.15).toFixed(3);
  } else {
    dsMesh.visible = false;
    dsLabel.div.innerHTML = '';
  }

  // integrand stem
  const f = fVal(t);
  const h = Math.max(0, Math.min(1.3, 1.3 * f / F_MAX));
  if (state.mode === 'f' && h > 0.004) {
    stem.visible = true; stemCap.visible = true;
    stem.position.copy(p); stem.scale.set(1, h, 1);
    stemCap.position.set(p.x, p.y + h, p.z);
    fLabel.pos.set(p.x, p.y + h, p.z);
    fLabel.div.innerHTML = 'f = ' + f.toFixed(2);
  } else {
    stem.visible = false; stemCap.visible = false;
    fLabel.div.innerHTML = '';
  }

  const acc = Math.SQRT2 * (Math.sin(t) * Math.sin(t) / 2 + Math.pow(t, 4) / 4);
  tVal.textContent = t.toFixed(2);
  slider.value = t;
  readout.textContent =
    't = ' + t.toFixed(3) + '\n' +
    '(x, y, z) = (' + x.toFixed(2) + ', ' + y.toFixed(2) + ', ' + z.toFixed(2) + ')\n' +
    'f = xy + z\u00b3 = ' + f.toFixed(3) + '\n' +
    '|r\u2032(t)| = \u221a2  \u2192  ds = \u221a2 dt\n' +
    '\u222b\u2080\u1d57 f ds = ' + acc.toFixed(3) + '\n' +
    'total = \u221a2\u00b7\u03c0\u2074/4 = ' + (Math.SQRT2 * Math.pow(PI, 4) / 4).toFixed(3);
}
ready = true;

function setMode(m) {
  state.mode = m;
  for (const k in btns) btns[k].classList.toggle('active', k === m);
  update();
}
btns.curve.onclick = () => setMode('curve');
btns.ds.onclick = () => setMode('ds');
btns.f.onclick = () => setMode('f');

slider.addEventListener('input', () => {
  anim = null;
  state.t = parseFloat(slider.value);
  update();
});

/* ── proportions toggle ────────────────────────────────────────────────── */
const pFig = document.getElementById('pFig'), pTrue = document.getElementById('pTrue');
let scaleTween = null;
let scaleMode = 'figure';

function setScaleMode(mode) {
  if (mode === scaleMode && !scaleTween) return;
  scaleMode = mode;
  pFig.classList.toggle('active', mode === 'figure');
  pTrue.classList.toggle('active', mode === 'true');
  const to = mode === 'figure' ? K_FIG : K_TRUE;
  scaleTween = { from: { x: K.x, y: K.y, z: K.z }, to, start: performance.now(), dur: 700 };
}
pFig.onclick = () => setScaleMode('figure');
pTrue.onclick = () => setScaleMode('true');

/* ── tweening / animation ──────────────────────────────────────────────── */
let anim = null;
const ease = (p) => p * p * (3 - 2 * p);
function tweenTo(target, dur) {
  anim = { from: state.t, to: target, start: performance.now(), dur: dur, linear: false };
}
document.getElementById('btnTrace').addEventListener('click', () => {
  state.t = 0; update();
  anim = { from: 0, to: PI, start: performance.now(), dur: 6000, linear: true };
});

(function loop() {
  requestAnimationFrame(loop);
  if (scaleTween) {
    const p = Math.min(1, (performance.now() - scaleTween.start) / scaleTween.dur);
    const e = ease(p);
    K.x = scaleTween.from.x + (scaleTween.to.x - scaleTween.from.x) * e;
    K.y = scaleTween.from.y + (scaleTween.to.y - scaleTween.from.y) * e;
    K.z = scaleTween.from.z + (scaleTween.to.z - scaleTween.from.z) * e;
    rebuild();
    if (p >= 1) scaleTween = null;
  }
  if (anim) {
    const p = Math.min(1, (performance.now() - anim.start) / anim.dur);
    const e = anim.linear ? p : ease(p);
    state.t = anim.from + (anim.to - anim.from) * e;
    update();
    if (p >= 1) anim = null;
  }
})();

/* ── demo steps ────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Start of the path', text: 'At t = 0 the point sits at (1, 0, 0) on the bottom of the box, the labeled starting point of C.', t: 0, mode: 'curve' },
  { title: 'A quarter turn up', text: 'At t = \u03c0/2 the point is at (0, 1, \u03c0/2): the helix has swung a quarter turn in y while rising halfway up the box.', t: 1.5708, mode: 'ds' },
  { title: 'Weighting by the integrand', text: 'Each arc piece ds = \u221a2 dt is multiplied by f = xy + z\u00b3 = cos t sin t + t\u00b3; watch the weight grow rapidly as z climbs.', t: 2.4, mode: 'f' },
  { title: 'End of the path', text: 'At t = \u03c0 the point reaches (\u22121, 0, \u03c0) at the top back corner, completing the half-turn helix.', t: 3.14159, mode: 'f' }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  setMode(s.mode);
  tweenTo(s.t, 900);
  narr.innerHTML = '<b>' + (stepIdx + 1) + '. ' + s.title + '</b><br>' + s.text;
}
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);

narr.innerHTML = '<b>Explore</b><br>Drag the t slider, switch the display mode, or step through the demo.';
setMode('curve');
update();
// @FIGURE_CODE_END

